"""Render runtime and repeatability evidence from the shared result summary."""

import json
from pathlib import Path


def main():
    summary = json.loads(Path("results/summary.json").read_text(encoding="utf-8"))
    validation = summary["validation"]
    timings, checks = validation["timings"], validation["checks"]
    lines = ["# Runtime and repeatability", "",
             "Generated by `python scripts/document_validation.py` from `results/summary.json`.", "",
             "Wall time includes imports, runtime startup, training, scoring, evaluation and output writing. It varies with hardware and other activity. These are observed runs, not a guarantee for a different machine. Every timing below uses the complete reproduction setup; reduced smoke runs are excluded.", "",
             "| Run | Device | Workers | GPU reservation | Wall (s) | Bound (s) | Within bound |",
             "|---|---|---|---|---|---|---|"]
    for row in timings:
        lines.append(f"| `{row['path']}` | {row['device']} | {row['workers']} | {row['gpu_fraction']} | {row['wall_seconds']:.3f} | {row['bound_seconds']} | {row['within_bound']} |")
    lines += ["", "Hardware and software versions are recorded in each run's metadata. Incomplete runs are omitted from this table and never treated as successful timings.", ""]
    for row in validation.get("failed_runs", []):
        lines += [f"Failed attempt: `{row['path']}`, device `{row['device']}`, workers {row['workers']}, GPU reservation {row['gpu_fraction']}, stopped after {row['wall_seconds']:.3f} seconds. The failure and full exception are preserved in its metadata; this is not a completed runtime measurement.", ""]
    lines += [
              "## Comparisons", ""]
    for name in ["repeatability", "cross_device", "gpu_scheduling"]:
        if name not in checks:
            lines += [f"- {name}: pending."]
            continue
        result = checks[name]
        lines += [f"### {name}", "", f"Mode: `{result['mode']}`. Passed: **{result['passed']}**. All recorded artifacts byte-identical: **{result['byte_identical']}**.", "",
                  f"Runs: `{result['paths'][0]}` and `{result['paths'][1]}`.", "",
                  "| Artifact | First SHA-256 | Second SHA-256 |", "|---|---|---|"]
        for file, hashes in result["hashes"].items():
            lines.append(f"| {file} | `{hashes[0]}` | `{hashes[1]}` |")
        lines += ["", "| Quantity | Maximum absolute difference |", "|---|---|"]
        lines += [f"| {key} | {value:.12g} |" for key, value in result["max_absolute_differences"].items()]
        lines += ["", f"Final accuracy difference: {result['final_accuracy_difference']:.12g}. Timing is excluded from byte identity. Cross-device acceptance uses the previously declared final-accuracy tolerance; it does not imply identical score or payout trajectories.", ""]
    smokes = checks.get("attack_smokes", [])
    lines += ["", "## Attack smoke coverage", "",
              "| Attack | Rounds | Adversary participations | Status |", "|---|---|---|---|"]
    for item in smokes:
        lines.append(f"| {item['attack']} | {item['rounds']} | {item['participations']} | {item['status']} |")
    lines += ["", "Smoke configurations reduce the dataset and local epochs. Their purpose is to exercise the transport and attack paths; they are not accuracy or performance measurements for the full protocol.", ""]
    Path("docs/VALIDATION.md").write_text("\n".join(lines), encoding="utf-8", newline="\n")
    cpu = [r for r in timings if r["device"] == "cpu"]
    gpu = [r for r in timings if r["device"] == "cuda"]
    block = ["<!-- generated validation start -->", "## Recorded validation", ""]
    for name, values in [("CPU", cpu), ("GPU", gpu)]:
        if values:
            block.append(f"{name}: {len(values)} completed {'run' if len(values) == 1 else 'runs'}, wall times {min(r['wall_seconds'] for r in values):.1f}–{max(r['wall_seconds'] for r in values):.1f} seconds; {sum(r['within_bound'] for r in values)} within the recorded runtime bound.")
    if "repeatability" in checks:
        block.append(f"Full CPU repeat: {'byte-identical' if checks['repeatability']['byte_identical'] else 'different'} participation logs, round logs and integer ledger.")
    block += ["", "See [runtime and repeatability evidence](docs/VALIDATION.md) for every run, resource setting and hash. Regenerate with `python scripts/summarize_validation.py` and `python scripts/document_validation.py`.", "<!-- generated validation end -->"]
    path = Path("README.md")
    readme = path.read_text(encoding="utf-8")
    start_marker, end_marker = "<!-- generated validation start -->", "<!-- generated validation end -->"
    if start_marker in readme:
        start = readme.index(start_marker)
        end = readme.index(end_marker, start) + len(end_marker)
        readme = readme[:start] + "\n".join(block) + readme[end:]
    else:
        readme = readme.replace("## Install on Windows", "\n".join(block) + "\n\n## Install on Windows", 1)
    path.write_text(readme, encoding="utf-8", newline="\n")
    print(f"Generated validation notes from {len(timings)} full runs and {len(checks)} evidence groups")


if __name__ == "__main__":
    main()
